// Current partial implementation. The proposed change removes clone().
final class QueuedSink implements Sink {
    private final BlockingQueue<byte[]> queue = new ArrayBlockingQueue<>(16);
    public void submit(byte[] record) throws InterruptedException {
        queue.put(record.clone());
    }
    void runWorker() throws InterruptedException {
        for (;;) {
            byte[] record = queue.take();
            recorder.append(record); // May wait before reading; synchronous, no retained callback.
        }
    }
}

